// Return a React component. Available props:
//   widget       - this widget's configuration (label, color, ...)
//   value        - current value of the linked variable
//   sendValue(v) - write the linked variable (or run the linked command)
//   readOnly, isRequesting
function Component({ widget, value, sendValue }) {
    return (
        <div className="d-flex flex-column align-items-center justify-content-center h-100">
            <h4>{value === undefined ? '-' : String(value)}</h4>
        </div>
    );
}
return Component;
